WITH enriched AS (SELECT id, order_date, discount, LEAD(amount) OVER w_recent AS next_amount, LAG(amount) OVER w_recent AS prev_amount, LAG(shipping_fee) OVER w_recent AS prev_shipping_fee, ROW_NUMBER() OVER w_recent AS seq_no, AVG(shipping_fee) OVER (PARTITION BY store_id, channel) AS store_id_avg_shipping_fee FROM orders WINDOW w_recent AS (PARTITION BY channel ORDER BY amount, id)) SELECT seq_no, CASE WHEN prev_amount >= 1420 THEN 'LARGE' ELSE 'SMALL' END AS prev_amount_tier, CASE WHEN discount >= 0.44 THEN 'HIGH' ELSE 'LOW' END AS discount_tier, AVG(prev_shipping_fee) AS avg_prev_shipping_fee, COUNT(*) AS row_count, COUNT(DISTINCT id) AS distinct_ids, ROUND(AVG(discount), 2) AS avg_discount, COUNT(*) AS cnt FROM enriched GROUP BY seq_no, CASE WHEN prev_amount >= 1420 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN discount >= 0.44 THEN 'HIGH' ELSE 'LOW' END HAVING AVG(prev_shipping_fee) < 1000000 ORDER BY avg_discount DESC NULLS FIRST;
